// GAME-TRIVIA fixtures (JAMAA-PLATFORM §6.1, §6.2: lane A publishes them first; lanes B and C code against them).
// Every file under shared/fixtures/v2/games/trivia/ is generated by this deterministic scenario (seed 4404, the demo
// quiz of shared/src/testing/catalogs/trivia.ts, a scripted clock) through the REAL room engine and projections.
//   write:  pnpm --filter @jamaa/shared exec tsx test/games/trivia/fixtures-gen.ts
//   check:  the fixtures test (shared/test/games/trivia/fixtures.test.ts) fails when a file is stale.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { ColorId, Locale } from "../../../src/constants";
import { errorMessageKey } from "../../../src/protocol/errors";
import type { ErrorCode } from "../../../src/protocol/errors";
import type { TriviaIntent, TriviaState } from "../../../src/games/trivia/engine/types";
import type { RoomIntent } from "../../../src/room/types";
import { TRIVIA_DEMO_CATALOG, withTrivia } from "../../../src/testing/catalogs/trivia";
import { ALL_TV_GAMES, RoomHarness } from "../../../src/testing/room";

export const TRIVIA_FIXTURE_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "fixtures", "v2", "games", "trivia");
export const TRIVIA_FIXTURE_SEED = 4404;
const T0 = 1_790_000_000_000;

const CAST: { name: string; color: ColorId; id: string; locale: Locale }[] = [
  { name: "Rami", color: "coral", id: "p_0a1b2c3d4e5f60718293a4b5", locale: "en" },
  { name: "Léa", color: "azure", id: "p_1b2c3d4e5f60718293a4b5c6", locale: "fr" },
  { name: "نور", color: "jade", id: "p_2c3d4e5f60718293a4b5c6d7", locale: "ar" },
  { name: "Sam", color: "lemon", id: "p_3d4e5f60718293a4b5c6d7e8", locale: "en" },
  { name: "Zoé", color: "grape", id: "p_4e5f60718293a4b5c6d7e8f9", locale: "fr" },
];
const [RAMI, LEA, NOUR, SAM, ZOE] = CAST.map((c) => c.id) as [string, string, string, string, string];

const json = (v: unknown): string => JSON.stringify(v, null, 2) + "\n";

function harness(locale: Locale): RoomHarness {
  const content = withTrivia(TRIVIA_DEMO_CATALOG);
  const h = new RoomHarness({
    seed: TRIVIA_FIXTURE_SEED, now: T0, roomCode: "QZNT", joinUrl: "https://play.example.workers.dev/QZNT",
    contentLocale: locale, content, fullContent: content, enabledGames: ["mishana", "trivia"], tvGames: ALL_TV_GAMES,
  });
  for (let i = 0; i < 4; i++) {
    const c = CAST[i]!;
    h.now = T0 + i;
    h.join(c.id, c.name, c.color, c.locale);
  }
  h.now = T0 + 1_000;
  return h;
}

const trivia = (h: RoomHarness): TriviaState => {
  const g = h.state.game;
  if (!g || g.id !== "trivia") throw new Error("no trivia instance");
  return g.state as TriviaState;
};
const game = (h: RoomHarness, by: string | null, i: TriviaIntent): void => {
  if (by === null) h.tv({ type: "GAME", gameId: "trivia", i });
  else h.p(by, { type: "GAME", gameId: "trivia", i });
};
/** Jump to the active game's deadline and TICK (the alarm). */
function expire(h: RoomHarness): void {
  const at = trivia(h).deadline?.at;
  if (at === undefined) throw new Error(`no deadline in ${trivia(h).phase}`);
  h.now = Math.max(h.now, at);
  h.sys({ type: "TICK" });
}
function until(h: RoomHarness, phase: TriviaState["phase"]): void {
  for (let i = 0; i < 100 && trivia(h).phase !== phase; i++) expire(h);
  if (trivia(h).phase !== phase) throw new Error(`never reached ${phase}`);
}
const right = (h: RoomHarness): number => trivia(h).cur!.correctIndex;
const wrong = (h: RoomHarness): number => (right(h) + 1) % trivia(h).cur!.options.length;
/** In ANSWER: each [player, right?, ms after the window opened]. */
function answerAll(h: RoomHarness, plan: [string, boolean, number][]): void {
  const open = trivia(h).cur!.answerOpenAt!;
  for (const [id, ok, ms] of [...plan].sort((a, b) => a[2] - b[2])) {
    if (trivia(h).phase !== "ANSWER") break;
    h.now = open + ms;
    game(h, id, { type: "ANSWER", choice: ok ? right(h) : wrong(h) });
  }
}

/** Returns `<name>` → file content (pretty-printed, trailing newline). */
export function generateTriviaFixtures(): Map<string, string> {
  const files = new Map<string, string>();
  const put = (name: string, v: unknown): void => { files.set(name, json(v)); };

  // ---------------- client → server
  let ref = 100;
  const action = (name: string, a: RoomIntent): void => put(`c2s.action.${name}.json`, { v: 2, t: "action", id: String(++ref), a });
  action("open_game.trivia", { type: "OPEN_GAME", gameId: "trivia" });
  action("update_game_settings.trivia", { type: "UPDATE_GAME_SETTINGS", gameId: "trivia", patch: { quizId: "demo-quiz-01", length: "short", pace: "normal" } });
  action("game.trivia.answer", { type: "GAME", gameId: "trivia", i: { type: "ANSWER", choice: 2 } });
  action("game.trivia.host_advance", { type: "GAME", gameId: "trivia", i: { type: "HOST_ADVANCE" } });
  action("game.trivia.void_question", { type: "GAME", gameId: "trivia", i: { type: "VOID_QUESTION", questionId: "q004" } });
  action("game.trivia.end_game", { type: "GAME", gameId: "trivia", i: { type: "END_GAME" } });

  // ---------------- server → client errors (Trivia's own codes + the platform ones it uses)
  const error = (name: string, code: ErrorCode, r: string | null): void => put(`s2c.error.${name}.json`, { v: 2, t: "error", code, messageKey: errorMessageKey(code), ref: r });
  error("answer_invalid", "ANSWER_INVALID", "103");
  error("already_answered", "ALREADY_ANSWERED", "103");
  error("wrong_phase.trivia", "WRONG_PHASE", "103");

  // ---------------- one short game in English, seen by the TV and by phones
  const h = harness("en");
  const state = (name: string, view: unknown): void => put(`s2c.state.${name}.json`, { v: 2, t: "state", seq: h.state.version, serverNow: h.now, view });
  const tv = (name: string): void => state(`tv.${name}`, h.tvView());
  const player = (name: string, id: string | null): void => state(`player.${name}`, h.playerView(id));

  h.tv({ type: "OPEN_GAME", gameId: "trivia" });
  h.now += 1_000;
  tv("setup.trivia.one_quiz");
  player("setup.trivia.host", RAMI);
  h.tv({ type: "UPDATE_GAME_SETTINGS", gameId: "trivia", patch: { length: "short" } });
  h.now += 1_000;
  tv("setup.trivia.short");

  h.tv({ type: "START_GAME" });
  tv("playing.trivia.quiz_intro");
  player("playing.trivia.quiz_intro", LEA);

  // q1: READ → ANSWER (two locked in) → REVEAL
  expire(h);
  tv("playing.trivia.read");
  player("playing.trivia.read", LEA);
  expire(h);
  tv("playing.trivia.answer.open");
  answerAll(h, [[RAMI, true, 2_100], [LEA, false, 3_400]]);
  tv("playing.trivia.answer");
  player("playing.trivia.answer.locked", LEA);
  player("playing.trivia.answer.pad", SAM);
  answerAll(h, [[NOUR, true, 4_800], [SAM, true, 6_000]]);
  tv("playing.trivia.answer.all_in");
  expire(h);
  tv("playing.trivia.reveal");
  player("playing.trivia.reveal.correct", RAMI);
  player("playing.trivia.reveal.wrong", LEA);

  // A late joiner while PLAYING: dealt in by `join`, waiting for the next READ.
  h.join(ZOE, CAST[4]!.name, CAST[4]!.color, CAST[4]!.locale);
  player("playing.trivia.waiting", ZOE);

  // q2, q3 → the first LEADERBOARD
  expire(h);
  expire(h);
  answerAll(h, [[RAMI, true, 1_500], [LEA, true, 2_000], [NOUR, false, 2_500], [SAM, true, 9_000], [ZOE, true, 4_000]]);
  expire(h);
  player("playing.trivia.reveal.new", ZOE);
  expire(h);
  expire(h);
  answerAll(h, [[RAMI, true, 1_000], [LEA, true, 5_000], [NOUR, true, 1_200], [SAM, false, 700], [ZOE, false, 9_000]]);
  expire(h);
  tv("playing.trivia.reveal.streak");
  expire(h);
  tv("playing.trivia.leaderboard");
  player("playing.trivia.leaderboard", SAM);

  // q4: nobody right → Stumped; the host voids it from the pause menu.
  expire(h);
  expire(h);
  answerAll(h, [[RAMI, false, 3_000], [LEA, false, 3_500], [NOUR, false, 4_000], [SAM, false, 5_000], [ZOE, false, 6_000]]);
  expire(h);
  tv("playing.trivia.reveal.stumped");
  game(h, null, { type: "VOID_QUESTION", questionId: trivia(h).last!.questionId });
  tv("playing.trivia.reveal.voided");

  // q5 (everyone right: Genius), q6 (nobody answers: "Too slow, everyone!") → LEADERBOARD → FINAL_INTRO
  expire(h);
  expire(h);
  answerAll(h, [[RAMI, true, 2_000], [LEA, true, 2_200], [NOUR, true, 2_400], [SAM, true, 2_600], [ZOE, true, 2_800]]);
  expire(h);
  tv("playing.trivia.reveal.genius");
  until(h, "ANSWER");
  expire(h);
  tv("playing.trivia.reveal.too_slow");
  until(h, "LEADERBOARD");
  until(h, "FINAL_INTRO");
  tv("playing.trivia.final_intro");
  player("playing.trivia.final_intro", NOUR);

  // The final (×2)
  expire(h);
  tv("playing.trivia.read.final");
  expire(h);
  answerAll(h, [[RAMI, false, 2_000], [LEA, true, 2_500], [NOUR, true, 3_000], [SAM, true, 8_000], [ZOE, false, 1_000]]);
  expire(h);
  tv("playing.trivia.reveal.final");
  player("playing.trivia.reveal.final", LEA);
  expire(h);
  tv("playing.trivia.results");
  player("playing.trivia.results.host", RAMI);
  player("playing.trivia.results", NOUR);

  // ---------------- an Arabic room (RTL text, ar options; tiles are never mirrored), and HOLD
  const ar = harness("ar");
  const arState = (name: string, view: unknown): void => put(`s2c.state.${name}.json`, { v: 2, t: "state", seq: ar.state.version, serverNow: ar.now, view });
  ar.tv({ type: "OPEN_GAME", gameId: "trivia" });
  ar.now += 1_000;
  ar.tv({ type: "START_GAME" });
  expire(ar);
  expire(ar);
  answerAll(ar, [[NOUR, true, 1_800]]);
  arState("tv.playing.trivia.answer.ar", ar.tvView());
  arState("player.playing.trivia.answer.ar", ar.playerView(NOUR));
  answerAll(ar, [[RAMI, false, 2_000], [LEA, true, 2_500], [SAM, true, 4_000]]);
  expire(ar);
  arState("tv.playing.trivia.reveal.ar", ar.tvView());
  // Everyone drops before the next question: HOLD (the host may end the game from the pause menu).
  for (const c of CAST.slice(0, 4)) ar.sys({ type: "DISCONNECT", playerId: c.id });
  for (let i = 0; i < 5 && trivia(ar).phase !== "HOLD"; i++) expire(ar);
  arState("tv.playing.trivia.hold", ar.tvView());
  return files;
}

/** CLI: write the files (or `--check`: exit 1 when one would change). */
function main(): void {
  const check = process.argv.includes("--check");
  mkdirSync(TRIVIA_FIXTURE_DIR, { recursive: true });
  let stale = 0;
  for (const [name, content] of generateTriviaFixtures()) {
    const path = join(TRIVIA_FIXTURE_DIR, name);
    let current: string | null;
    try { current = readFileSync(path, "utf8"); } catch { current = null; }
    if (current === content) continue;
    if (check) { console.error(`stale fixture: ${name}`); stale++; }
    else { writeFileSync(path, content); console.log(`wrote ${name}`); }
  }
  if (check && stale > 0) process.exit(1);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
